{
  "IP": "neorv32_gpio",
  "Conceptual Assets": [
    {
      "Concept ID": "C1",
      "Concept Name": "GPIO output value",
      "Unit": "neorv32_gpio",
      "Information": "The GPIO output word held by the unit determines the levels driven on the external GPIO pins and can be read back by the bus.",
      "Rubric": {
        "Confidentiality": "yes",
        "Integrity": "yes",
        "Availability": "no",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "The output value may contain application data and is exposed through gpio_o and bus read-back at lines 84 and 112. A bus write changes the stored output value at line 74, allowing an attacker to alter the GPIO levels.",
      "Objectives At Risk": [
        "C",
        "I"
      ],
      "Attack": "An attacker could observe the GPIO output or read it back, or write a different output word to change externally controlled signals.",
      "Enters Through": [
        "bus_req_i.data"
      ],
      "Leaves Through": [
        "bus_rsp_o.data",
        "gpio_o"
      ],
      "Entry Lines": [
        74
      ],
      "Held Lines": [
        74
      ],
      "Exit Lines": [
        84,
        112
      ]
    },
    {
      "Concept ID": "C2",
      "Concept Name": "GPIO input data",
      "Unit": "neorv32_gpio",
      "Information": "The sampled GPIO input word represents the levels received from the external pins and is used for bus read-back and interrupt detection.",
      "Rubric": {
        "Confidentiality": "yes",
        "Integrity": "yes",
        "Availability": "no",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "The sampled input may contain application data and is exposed by the bus read at line 83. The input sample is captured into the unit at line 103, so changing the received value can alter read-back and interrupt behavior.",
      "Objectives At Risk": [
        "C",
        "I"
      ],
      "Attack": "An attacker could observe the input through a bus read or spoof the GPIO levels to cause incorrect sampled data and interrupt behavior.",
      "Enters Through": [
        "gpio_i"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        103
      ],
      "Held Lines": [
        103
      ],
      "Exit Lines": [
        83
      ]
    },
    {
      "Concept ID": "C3",
      "Concept Name": "Pending GPIO interrupt state",
      "Unit": "neorv32_gpio",
      "Information": "The pending-interrupt state records GPIO trigger events that remain pending and determines the interrupt status returned to software and signaled to the CPU. It has no entry port because the state is formed internally from the trigger logic and interrupt controls.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "The pending state is updated by the interrupt state logic at line 141 and can be altered or cleared through the interrupt-enable and clear controls used there. Clearing or suppressing the pending state at line 141 can prevent the CPU interrupt at line 142 and block required interrupt servicing.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could change the pending state or suppress it through the interrupt control path so that a required GPIO interrupt is lost.",
      "Enters Through": [],
      "Leaves Through": [
        "bus_rsp_o.data",
        "cpu_irq_o"
      ],
      "Entry Lines": [],
      "Held Lines": [
        141
      ],
      "Exit Lines": [
        88,
        142
      ]
    },
    {
      "Concept ID": "C4",
      "Concept Name": "GPIO interrupt trigger decision",
      "Unit": "neorv32_gpio",
      "Information": "The per-GPIO trigger decision identifies the configured level or transition condition that should create a pending interrupt.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "The trigger decision is produced by the level and transition logic at lines 125 through 129 and controls whether the pending state is set at line 141. Altering the sampled input or the trigger-selection controls can produce false interrupts or suppress required ones.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could manipulate the trigger inputs or selection path to generate spurious interrupts or prevent a real GPIO event from reaching the CPU.",
      "Enters Through": [
        "gpio_i"
      ],
      "Leaves Through": [
        "cpu_irq_o"
      ],
      "Entry Lines": [
        103
      ],
      "Held Lines": [
        125,
        126,
        127,
        128,
        129
      ],
      "Exit Lines": [
        142
      ]
    }
  ],
  "Not Kept": [
    {
      "Candidate Name": "Interrupt trigger mode and polarity settings",
      "Candidate Unit": "neorv32_gpio",
      "Merged Into": "",
      "Why Not Kept": "The bus-written settings only tune the interrupt-request output, so the Port options rule bars them as pieces of their own."
    },
    {
      "Candidate Name": "Interrupt enable setting",
      "Candidate Unit": "neorv32_gpio",
      "Merged Into": "",
      "Why Not Kept": "The bus-written enable only tunes whether the interrupt-request output is produced, so the Port options rule bars it as a separate piece."
    },
    {
      "Candidate Name": "Interrupt pending clear control",
      "Candidate Unit": "neorv32_gpio",
      "Merged Into": "",
      "Why Not Kept": "The bus-written clear control only tunes the interrupt-request output by clearing or retaining pending state, so the Port options rule bars it as a separate piece."
    },
    {
      "Candidate Name": "GPIO input synchronization copy",
      "Candidate Unit": "neorv32_gpio",
      "Merged Into": "C2",
      "Why Not Kept": ""
    },
    {
      "Candidate Name": "CPU interrupt status indication",
      "Candidate Unit": "neorv32_gpio",
      "Merged Into": "C3",
      "Why Not Kept": ""
    },
    {
      "Candidate Name": "Bus access command and handshake",
      "Candidate Unit": "neorv32_gpio",
      "Merged Into": "",
      "Why Not Kept": "The access fields are part of the register information they select or write, while the acknowledge and constant error fields are bus-handshake information rather than an independent asset."
    },
    {
      "Candidate Name": "Clock and reset control",
      "Candidate Unit": "neorv32_gpio",
      "Merged Into": "",
      "Why Not Kept": "Clock and reset inputs and their reset copies are excluded by the clock-and-reset rule."
    }
  ],
  "Notes": []
}
